insert into public.collections (slug,title,description,collection_type,is_published,sort_order) values ('taller-365-ley-asuncion','Taller de 365 días','Ley de Asunción · 365 días','taller',true,20) on conflict (slug) do update set title=excluded.title,description=excluded.description,collection_type=excluded.collection_type,is_published=excluded.is_published,sort_order=excluded.sort_order,updated_at=now();
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-antes-de-algo-importante','moment','Antes de una reunion, entrevista o examen','Pará un segundo antes de entrar. Cerra los ojos si podes, o aunque sea bajá la mirada.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-ansiedad','moment','Cuando te agarro la ansiedad','Pará. Estás acá, ahora, y ahora mismo estás bien. La ansiedad no vive en el ahora: vive en un futuro que todavia no pasó y que capaz nunca pase.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-dormir','moment','Cuando no podes parar la cabeza para dormir','Acostate. Aflojá el cuerpo, de los pies a la cabeza. Pies, piernas, panza, hombros, mandibula, frente. Todo suelto.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-pelea','moment','Cuando te peleaste con alguien','Respira. Todavia estás caliente, y desde el enojo no se ve claro. Dale un minuto a la cabeza antes de hacer o decir algo de lo que te arrepientas.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-mala-noticia','moment','Cuando te llego una mala noticia','Respira. Recien te sacudieron, y es normal que estes en shock. No tenes que resolver nada ahora mismo. Solo respirar y sostenerte.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-decision','moment','Antes de tomar una decision dificil','Pará. No decidas desde el ruido. Las mejores decisiones no salen de pensar mas fuerte, salen de aflojar y escuchar.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-soledad','moment','Cuando te sentis solo','Respira. La soledad duele, pero escuchame: estar solo y sentirse solo no son lo mismo. Podes estar rodeado de gente y sentirte solo, o estar solo y sentirte acompañado. La diferencia esta adentro, no afuera.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-bajon','moment','Cuando estas bajoneado sin saber por que','Está bien no estar bien. No todo tiene que tener explicacion. A veces el animo baja y no hay un motivo claro, y forzarte a encontrarlo solo lo empeora.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-hablar-en-publico','moment','Antes de hablar en publico','Pará antes de subir. Respira hondo, desde la panza, tres veces.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-culpa','moment','Cuando te ataca la culpa','Respira. La culpa es util un minuto — para darte cuenta de algo — pero despues se vuelve un latigo que no sirve para nada mas que lastimarte.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-arrancar-el-dia','moment','Para arrancar el dia con fuerza','Antes de meterte en el dia, dame un minuto. Respira hondo, estirate, sentí el cuerpo despertando.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-cerrar-el-dia','moment','Para cerrar el dia en paz','El dia terminó. Hiciste lo que pudiste con lo que tenias. Alcanza.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-miedo','moment','Cuando tenes miedo de algo','Respira. El miedo te agarró, y el miedo grita fuerte, pero casi siempre miente sobre el tamaño de las cosas.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-gratitud','moment','Cuando queres sentirte mejor rapido','Pará un momento. Hay un atajo para cambiar como te sentis, y es mas simple de lo que parece: la gratitud.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('moment-confianza','moment','Cuando necesitas un envion de seguridad','Pará. Necesitas confianza y la vas a conseguir, pero no de afuera: de adentro. La confianza no te la da nadie. La elegis vos.
insert into public.content_items (slug,content_type,title,body,source_url,visibility,is_published,metadata) values ('taller-365-dia-001','law_course_day','Día 001','','internal://taller-365/dia-001','public',true,'{"day":1,"title":"El Despertar del \"Yo Soy\" (La Conciencia Desnuda)","source":"Tomo VIII (A tus órdenes / Tu fe es tu fortuna) y Tomo I (Está dentro de ti)","audio_script":"Bienvenido al primer día de un viaje que transformará para siempre la manera en que experimentas la realidad (...)\n\nDurante mucho tiempo se te ha enseñado a creer que eres una criatura a merced de circunstancias externas: un cuerpo vulnerable que navega en un mundo lleno de obstáculos, buscando desesperadamente que las cosas cambien afuera para poder sentir paz adentro (...) Hoy, en este primer instante, esa vieja ilusión comienza a desmoronarse.\n\nEscucha con atención lo que Neville Goddard descubrió en lo más profundo de la sabiduría ancestral: la conciencia de ser es la única realidad. Antes de que puedas decir «yo soy pobre», «yo soy rico», «yo estoy enfermo» o «yo soy exitoso», existe una verdad primaria, pura e intocable: simplemente... YO SOY.\n\nEse «Yo Soy» no es tu nombre, no es tu profesión, no es tu historia pasada ni el saldo de tu cuenta bancaria. Es la presencia viva, sin forma ni límite, que habita en el centro de tu pecho. Es el Dios vivo encarnado en ti.\n\nMoisés preguntó en la zarza ardiente: «¿Quién diré que me ha enviado?». Y la respuesta no fue un ser lejano en el cielo, sino la verdad eterna: «YO SOY me ha enviado a vosotros».\n\nCuando dices «Yo Soy», estás pronunciando el nombre del Creador del universo dentro de tu propia conciencia. Todo lo que coloques después de esas dos palabras sagradas se convertirá en la tela con la que vestirás tu mundo visible. Si dices «yo soy débil», la conciencia te obedecerá fielmente y creará debilidad. Pero si aprendes a despojarte de todas las etiquetas y descansas en la pura conciencia de ser, recuperas el poder absoluto de moldear tu destino.\n\nHoy no tienes que salir a luchar contra el mundo (...) No tienes que convencer a nadie ni manipular los acontecimientos exteriores. Tu única tarea hoy es recordar quién eres verdaderamente. Eres la conciencia infinita que observa este instante.\n\nCierra los ojos por un momento (...) Respira profundo (...) Y en el santuario de tu silencio interior, suelta todas tus cargas. Olvida tu nombre por un minuto. Olvida tus problemas. Olvida las limitaciones que el tiempo y el miedo te impusieron. Siente únicamente la maravillosa, ilimitada y luminosa sensación de existir: YO SOY (...)\n\nDesde este espacio sin forma, todo lo que sueñas ya es posible. Hoy despiertas al Creador que siempre estuvo esperando por ti.","foundation":"La base sobre la que se asienta toda la enseñanza de Neville Goddard es una verdad ontológica radical: la conciencia de ser es la única y absoluta sustancia de la realidad. No existen dos poderes en el universo —un Dios afuera y tú sufriendo abajo—, sino una sola presencia creadora que se individualiza en cada ser humano a través del sentimiento de existencia.\n\nAntes de que te identifiques con cualquier condición física o social, tú eres. Ese estado primordial e incondicionado es lo que la Biblia llama el nombre eterno de Dios: YO SOY (Éxodo 3:14).\n\n«La conciencia es la única realidad. Las cosas viven sólo mientras yo soy consciente de serlas; así que, para realizar un deseo, debe aplicarse el principio: la conciencia se hace consciente de ser lo deseado, fijándose a la forma y dándole vida a aquello que hasta entonces era un deseo muerto».  \n— Neville Goddard, Tu fe es tu fortuna (Tomo VIII).","psychology":"El ser humano ordinario comete el error de unir de manera mecánica el sagrado «Yo Soy» a estados de indignidad, escasez y dolor: «Yo soy torpe», «Yo soy propenso a enfermarme», «Yo nunca tengo suerte en el amor». Cada vez que haces esto, estás emitiendo un mandato creador irrevocable a tu subconsciente. La conciencia es completamente impersonal: no juzga si lo que afirmas es bueno o malo para ti; simplemente toma tu autodefinición y la materializa en tu entorno como hechos tangibles.\n\nEl primer paso de la maestría consiste en desvestir al Yo Soy. Antes de asumir un nuevo deseo de salud o riqueza, debes aprender a regresar a la conciencia desnuda, al estado previo a todas las definiciones. En ese vacío sin límites, todas las cadenas del pasado se disuelven porque no hay memoria ni condicionamiento: sólo presencia pura.","exercise":"1. La Pausa de Quietud: Siéntate cómodamente en un lugar tranquilo durante 5 a 10 minutos. Cierra los ojos y relaja conscientemente la mandíbula, los hombros y el pecho.\n2. Desprenderse de la Máscara: Comienza a retirar tu atención de tu cuerpo y de tus circunstancias. Di mentalmente: «No soy mi cuerpo, no soy mi nombre, no soy mis cuentas pendientes, no soy mi pasado».\n3. Habitar el \"Yo Soy\": Cuando sientas que los bordes de tu personalidad se difuminan, pronuncia internamente con lentitud y reverencia: «YO SOY... YO SOY... YO SOY». No añadas nada más. Permanece suspendido en esa sensación de mera existencia, sintiendo el gozo silencioso de ser.\n4. Anclaje Diario: Durante el día, cada vez que sientas ansiedad o prisa, haz una respiración profunda y recuérdate en silencio: «Yo Soy antes de cualquier problema. Yo Soy la presencia creadora»."}'::jsonb) on conflict (slug) do update set content_type=excluded.content_type,title=excluded.title,body=excluded.body,source_url=excluded.source_url,visibility=excluded.visibility,is_published=excluded.is_published,metadata=excluded.metadata,updated_at=now();
